// בונה את בקשת הצ'אט ל-Ollama מתוך הודעת המשתמש + הקשר היום.
const webhook = $('Webhook').first().json;
const body = webhook.body || webhook;
const chatInput = body.chatInput || body.message || body.text || '';
const sessionId = body.sessionId || 'jarvis-local';

const brief = $('Get Daily Brief').first()?.json || {};
const week = $('Get Week Calendar').first()?.json || {};

const digest = brief.digest || '(אין סיכום יומי זמין)';
const weekLine = (week.days || [])
  .flatMap(d => (d.events || []).map(e => `${d.weekday}: ${e.summary} (${e.when})`))
  .slice(0, 10)
  .join('; ') || 'אין אירועים השבוע';

const system = [
  'אתה JARVIS — עוזר אישי בעברית של חיים קריספין.',
  'אתה רץ מקומית מול Ollama ומחובר למערכת magnet-studio (מענה יומי, יומן, דיור, הגרלה, מצב מחשב).',
  'תשובות קצרות, מדויקות ומעשיות. אם חסר מידע — אמור זאת, אל תמציא.',
  '',
  'הקשר היום (סיכום מובנה):',
  digest,
  '',
  'יומן השבוע: ' + weekLine
].join('\n');

return [{
  json: {
    sessionId,
    model: 'llama3.1:latest',
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: chatInput }
    ]
  }
}];
